import{_ as t,o,c as s,a2 as d}from"./chunks/framework.GbRRgL9t.js";const g=JSON.parse('{"title":"架构说明","description":"","frontmatter":{},"headers":[],"relativePath":"development/architecture.md","filePath":"development/architecture.md","lastUpdated":1789902237000}'),a={name:"development/architecture.md"};function c(n,e,r,i,l,p){return o(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="架构说明" tabindex="-1">架构说明 <a class="header-anchor" href="#架构说明" aria-label="Permalink to &quot;架构说明&quot;">​</a></h1><p>CircleChat 以<strong>单进程</strong>运行为设计目标：前端静态资源由后端内部静态服务托管，后端一个进程同时承载 HTTP API、WebSocket 与文件上传。运行时零第三方依赖。</p><h2 id="总体分层" tabindex="-1">总体分层 <a class="header-anchor" href="#总体分层" aria-label="Permalink to &quot;总体分层&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 (Vue 3 SPA)</span></span>
<span class="line"><span>   │  HTTP /api/*          WebSocket /ws</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Nitro 外壳 (node-server 预设)</span></span>
<span class="line"><span>   │  server/routes/[...].ts 全量兜底路由</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>runtime.ts (核心运行时，原 server.js 1:1 迁移)</span></span>
<span class="line"><span>   ├── handleHttp     HTTP 路由</span></span>
<span class="line"><span>   ├── handleWsText   WebSocket 业务</span></span>
<span class="line"><span>   ├── 上传（单次 + 分片）</span></span>
<span class="line"><span>   └── serveStatic    静态资源托管</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>server/lib/*  领域模块</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>SQLite (node:sqlite) / 文件系统 (data/)</span></span></code></pre></div><h2 id="后端模块" tabindex="-1">后端模块 <a class="header-anchor" href="#后端模块" aria-label="Permalink to &quot;后端模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>职责</th></tr></thead><tbody><tr><td><code>server/lib/runtime.ts</code></td><td><strong>主运行时</strong>：HTTP 路由调度（<code>handleApi</code>）、WebSocket 业务（<code>handleWsText</code>）、上传（单次 / 分片断点）落盘、静态服务、审计调用</td></tr><tr><td><code>server/lib/auth.ts</code></td><td>注册、登录、会话（Cookie token）、2FA（TOTP）、登录限速、内置管理员</td></tr><tr><td><code>server/lib/store.ts</code></td><td>消息存储（SQLite），<code>add</code> / <code>recall</code> / <code>toggleReaction</code>，每房间保留最近 <code>MAX_MESSAGES</code> 条</td></tr><tr><td><code>server/lib/groups.ts</code></td><td>群组 CRUD、成员资格、入群申请、群日志</td></tr><tr><td><code>server/lib/friends.ts</code></td><td>好友关系、<code>pairKey</code>（私聊配对键）</td></tr><tr><td><code>server/lib/moderate.ts</code></td><td>处罚判定：禁言 / 封禁 / IP 封禁（<code>blockFor</code>）</td></tr><tr><td><code>server/lib/mailbox.ts</code></td><td>站内信箱：公告表 + 通知表（按用户分发）</td></tr><tr><td><code>server/lib/audit.ts</code></td><td>审计日志表</td></tr><tr><td><code>server/lib/log.ts</code></td><td>访问日志（写 <code>data/access.log</code>，应用层网络监控）</td></tr><tr><td><code>server/lib/migrate.ts</code></td><td>数据库结构校验与自动迁移（兼容旧库）</td></tr><tr><td><code>server/lib/ws.ts</code></td><td>WebSocket 协议实现：握手、帧编解码、掩码、Ping/Pong、Close</td></tr><tr><td><code>server/lib/filetypes.ts</code></td><td>上传类型白名单、图片魔数嗅探</td></tr></tbody></table><h2 id="启动与路由" tabindex="-1">启动与路由 <a class="header-anchor" href="#启动与路由" aria-label="Permalink to &quot;启动与路由&quot;">​</a></h2><ul><li><strong>入口</strong>：<code>server/plugins/bootstrap.ts</code>（Nitro 启动插件）：<code>migrate → auth.init → store.load → audit.load → mkdir(uploads) → 清理临时分片 → 定时清理过期文件</code>。</li><li><strong>HTTP 接入</strong>：<code>server/routes/[...].ts</code> 是<strong>全量兜底路由</strong>，把原生 <code>req/res</code> 转交给 <code>runtime.handleHttp</code>。因 node-server 预设的 <code>fromNodeHandler</code> 依赖的 <code>event.runtime.node</code> 未填充，该路由直接用 <code>event.node</code> 的原生 req/res，并等待 <code>finish/close</code> 后再 resolve。</li><li><strong>WS 升级</strong>：<code>server/plugins/ws.ts</code> 拦截升级请求，交给 <code>ws.accept</code>。</li></ul><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><ul><li><strong>入口</strong>：<code>src/main-{login,chat,group,admin}.ts</code> 分别对应四个应用（登录 / 聊天 / 群管理 / 管理后台）。</li><li><strong>请求层</strong>：<code>src/core/api.ts</code> 统一封装同源 fetch；<code>src/core/config.ts</code> 读取 <code>config.js</code> 的地址配置。</li><li><strong>核心</strong>：<code>src/core/</code>（如 <code>chat.ts</code>、<code>media.ts</code>、<code>format.ts</code>、<code>i18n.ts</code>）承载业务逻辑。</li><li><strong>组件</strong>：<code>src/components/</code> 含 <code>chat/</code>、<code>group/</code>、<code>admin/</code>、<code>login/</code>、<code>common/</code>。</li><li><strong>多语言</strong>：<code>src/i18n/messages/{zh,en,ja}.ts</code>。</li><li><strong>构建</strong>：Vite + Tailwind 4；产物 <code>public/dist/</code>。样式分两层：<code>public/css/</code>（全局，优先级高于 <code>@layer</code>）与组件内样式。</li></ul><h2 id="数据与文件" tabindex="-1">数据与文件 <a class="header-anchor" href="#数据与文件" aria-label="Permalink to &quot;数据与文件&quot;">​</a></h2><ul><li><strong>SQLite</strong>：<code>data/chatplus.db</code>（<code>node:sqlite</code>，Node ≥ 22.5）。用户、消息、群组、处罚、审计、公告、通知。</li><li><strong>上传</strong>：<code>public/uploads/</code>，由 <code>FILE_TTL_DAYS</code> 控制保留；单文件上限 100MB。</li><li><strong>日志</strong>：<code>data/access.log</code>（HTTP + WebSocket 全量连接日志）。</li></ul><h2 id="关键设计" tabindex="-1">关键设计 <a class="header-anchor" href="#关键设计" aria-label="Permalink to &quot;关键设计&quot;">​</a></h2><ul><li><strong>零第三方运行时依赖</strong>：后端仅用 Node 内建模块 + <code>node:sqlite</code>，无任何第三方运行时 npm 包。</li><li><strong>显示 / 请求地址分离</strong>：前端 <code>config.js</code> 的 <code>apiBase</code> / <code>displayBase</code> 解耦页面展示地址与真实请求地址。</li><li><strong>静态服务在进程内</strong>（<code>serveStatic:false</code>，由内部 <code>serveStatic</code> 处理），因此无需额外静态服务器即可访问前端资源。</li></ul>`,14)])])}const u=t(a,[["render",c]]);export{g as __pageData,u as default};
